# Regenerated by .github/workflows/release.yml on every tagged release, so the
# version and checksums below always match the published assets.
#
# The published asset is a Nuitka standalone build: compiled, so there is no
# interpreter and no readable source on disk. It is deliberately not a Nuitka
# *onefile* binary — onefile unpacks its whole payload on every single run, which
# made even `cib --help` take about four seconds. The directory form does not
# unpack anything and starts in well under a second.
class Cib < Formula
  desc "Real Google Chrome in a box — a Linux container or a macOS VM"
  homepage "https://github.com/sapn95/chrome-in-a-box"
  version "1.2.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/sapn95/chrome-in-a-box/releases/download/v1.2.0/cib-macos-arm64.tar.gz"
      sha256 "d6b8a9afc6fdf56c70531d289166fceb096a7c46bd385505eccbb3636717217c"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/sapn95/chrome-in-a-box/releases/download/v1.2.0/cib-linux-arm64.tar.gz"
      sha256 "52d4f19d2288d98cf0fd67bdb1061f82529538ac65cb8f5b694df334842a5205"
    end
    on_intel do
      url "https://github.com/sapn95/chrome-in-a-box/releases/download/v1.2.0/cib-linux-x86_64.tar.gz"
      sha256 "d04b2f322b88318dda7c587091da429eac222f73922d931f01c831fc5ade28a2"
    end
  end

  def install
    libexec.install Dir["*"]
    bin.install_symlink libexec/"cib"
  end

  test do
    assert_match "cib #{version}", shell_output("#{bin}/cib --version")
  end
end
